-- On the Way: initial PostgreSQL/PostGIS schema. Apply to a dedicated project DB after backup and review.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TYPE booking_status AS ENUM ('requested','matching','driver_assigned','driver_arriving','in_progress','completed','cancelled','payment_pending','paid','disputed');
CREATE TYPE vehicle_type AS ENUM ('car','bike','rickshaw');
CREATE TYPE account_role AS ENUM ('passenger','driver','operator','platform_admin');
CREATE TABLE IF NOT EXISTS accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pi_uid TEXT UNIQUE, role account_role NOT NULL, display_name TEXT, country_code CHAR(2), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (pi_uid IS NULL OR length(pi_uid) BETWEEN 1 AND 160));
CREATE TABLE IF NOT EXISTS driver_profiles (account_id UUID PRIMARY KEY REFERENCES accounts(id) ON DELETE RESTRICT, verification_status TEXT NOT NULL DEFAULT 'pending' CHECK (verification_status IN ('pending','under_review','verified','rejected','suspended')), availability_status TEXT NOT NULL DEFAULT 'offline' CHECK (availability_status IN ('offline','available','busy','suspended')), service_city TEXT, verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vehicles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_account_id UUID NOT NULL REFERENCES driver_profiles(account_id) ON DELETE RESTRICT, vehicle_type vehicle_type NOT NULL, make TEXT, model TEXT, model_year SMALLINT, registration_country CHAR(2), verification_status TEXT NOT NULL DEFAULT 'pending' CHECK (verification_status IN ('pending','verified','rejected','suspended')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_zones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), country_code CHAR(2) NOT NULL, city_name TEXT NOT NULL, zone_name TEXT NOT NULL, boundary GEOGRAPHY(MULTIPOLYGON,4326), currency_code CHAR(3) NOT NULL, active BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(country_code,city_name,zone_name));
CREATE TABLE IF NOT EXISTS bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), passenger_account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT, driver_account_id UUID REFERENCES driver_profiles(account_id) ON DELETE RESTRICT, vehicle_type vehicle_type NOT NULL, status booking_status NOT NULL DEFAULT 'requested', pickup_label TEXT NOT NULL, pickup_latitude DOUBLE PRECISION NOT NULL CHECK (pickup_latitude BETWEEN -90 AND 90), pickup_longitude DOUBLE PRECISION NOT NULL CHECK (pickup_longitude BETWEEN -180 AND 180), pickup_location GEOGRAPHY(POINT,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(pickup_longitude,pickup_latitude),4326)::geography) STORED, destination_label TEXT NOT NULL, destination_latitude DOUBLE PRECISION NOT NULL CHECK (destination_latitude BETWEEN -90 AND 90), destination_longitude DOUBLE PRECISION NOT NULL CHECK (destination_longitude BETWEEN -180 AND 180), destination_location GEOGRAPHY(POINT,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(destination_longitude,destination_latitude),4326)::geography) STORED, passenger_note TEXT CHECK (passenger_note IS NULL OR length(passenger_note)<=500), quoted_amount NUMERIC(20,8) CHECK (quoted_amount IS NULL OR quoted_amount>=0), currency_code CHAR(3), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS bookings_status_created_idx ON bookings(status,created_at DESC);
CREATE INDEX IF NOT EXISTS bookings_pickup_geo_idx ON bookings USING GIST(pickup_location);
CREATE INDEX IF NOT EXISTS bookings_destination_geo_idx ON bookings USING GIST(destination_location);
CREATE INDEX IF NOT EXISTS drivers_city_availability_idx ON driver_profiles(service_city,availability_status);
CREATE TABLE IF NOT EXISTS payment_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT, provider TEXT NOT NULL CHECK (provider='pi_network'), provider_payment_id TEXT UNIQUE, status TEXT NOT NULL CHECK (status IN ('created','approved','completed','cancelled','failed','refunded')), amount NUMERIC(20,8) NOT NULL CHECK (amount>0), currency_code CHAR(3) NOT NULL DEFAULT 'PI', verified_at TIMESTAMPTZ, raw_event_hash TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payment_events_booking_idx ON payment_events(booking_id,created_at DESC);
COMMIT;
